SELECT ?series ?seriesLabel WHERE {
  ?series wdt:P57 wd:Q281204;        # Created by Hilarie Ross Burton (to confirm her Wikidata item first)
          wdt:P449 wd:Q101489;        # Broadcast on The WB Television Network
          rdfs:label ?seriesLabel.
  FILTER(LANG(?seriesLabel) = "en")
}
LIMIT 10

